"""WRI (blind vs full, seed-2 checkpoints) and output-cap sensitivity (32k vs 64k), as specified in PREREG §11/§12. Descriptive; n is small and stated."""
import json, sys
from pathlib import Path
import numpy as np, pandas as pd
ROOT = Path(__file__).resolve().parents[1]; sys.path.insert(0, str(ROOT))
from wsarena.analysis.metrics import load_runs
rng = np.random.default_rng(2)
man = {e["sha256"][:12]: e for e in json.loads((ROOT / "configs/tasks/ckpt_manifest.json").read_text())["entries"] if e["status"] == "built"}
def get(exp):
    d = load_runs(ROOT / "runs" / exp); d = d[d["status"].isin(["verified", "failed"])].copy()
    d["arm"] = d["run_id"].str.split("__").str[2].str.replace("-blind", ""); d["ckpt_id"] = d["ckpt"].map(lambda c: man[c]["ckpt_id"]); return d
full, rep, blind, c32 = get("main-v1-t0"), get("main-v1-t0-rep"), get("main-v1-t0-blind"), get("main-v1-cap32k")
def boot(x, n=5000):
    x = np.asarray(x, float); b = [x[rng.integers(0, len(x), len(x))].mean() for _ in range(n)]; return x.mean(), np.percentile(b, 2.5), np.percentile(b, 97.5)
out = ["# A3 blind (WRI) and output-cap sensitivity (generated by scripts/analyze_blind_cap.py)", ""]
f = pd.concat([full[full.arm.isin(["sonnet55-medium", "opus55-medium"])], rep]).groupby(["ckpt_id", "arm"])["d_sr_id"].mean()   # full-weights reference: main run + replicate averaged
b = blind.groupby(["ckpt_id", "arm"])["d_sr_id"].mean()
j = pd.concat([f.rename("full"), b.rename("blind")], axis=1).dropna(); j["WRI"] = j["full"] - j["blind"]
out += ["## A3: weight-reliance index WRI = dSR(full weights, mean of the 2 runs) - dSR(blind)  (8 checkpoints x 2 arms)", "", j.round(3).reset_index().to_markdown(index=False), ""]
rows = []
for a in ("sonnet55-medium", "opus55-medium", "both"):
    x = j["WRI"] if a == "both" else j.xs(a, level="arm")["WRI"]; m, lo, hi = boot(x); rows.append([a, len(x), m, lo, hi, (x.abs() <= 0.05).mean()])
out += ["| arm | n | mean WRI | lo | hi | share |WRI|<=0.05 |", "|---|---|---|---|---|---|"] + [f"| {r[0]} | {r[1]} | {r[2]:+.3f} | {r[3]:+.3f} | {r[4]:+.3f} | {r[5]:.2f} |" for r in rows] + [""]
jl = j.reset_index(); jl["level"] = jl["ckpt_id"].map(lambda c: "L3" if "/s3/" in c else "L2")
out += ["By level:", "", jl.groupby(["level", "arm"])["WRI"].agg(["mean", "count"]).round(3).to_markdown(), ""]
# blind runs have the same mechanism mix?
out += [f"Blind runs: valid-patch rate {blind['valid_patch_rate'].mean():.2f} (full main runs, same arms: {full[full.arm.isin(['sonnet55-medium','opus55-medium'])]['valid_patch_rate'].mean():.2f}); mean frac_changed blind {blind['frac_changed'].mean():.2f} vs full {full[full.arm.isin(['sonnet55-medium','opus55-medium'])]['frac_changed'].mean():.2f}", ""]
# cap
f64 = full.groupby(["ckpt_id", "arm"])["d_sr_id"].mean(); c = c32.groupby(["ckpt_id", "arm"])["d_sr_id"].mean()
k = pd.concat([f64.rename("64k"), c.rename("32k")], axis=1).dropna(); k["64k - 32k"] = k["64k"] - k["32k"]
out += ["## P2: output cap 32k vs 64k (paired, same checkpoint and arm; 4 checkpoints x 2 arms; one 32k run vs one 64k run each)", "", k.round(3).reset_index().to_markdown(index=False), ""]
rows = [[a, len(k.xs(a, level='arm')), k.xs(a, level='arm')["64k - 32k"].mean(), c32[c32.arm == a]["n_budget_exhausted"].sum(), full[(full.arm == a) & full.ckpt_id.isin(c32.ckpt_id)]["n_budget_exhausted"].sum(),
         c32[c32.arm == a]["tok_out"].max(), full[(full.arm == a) & full.ckpt_id.isin(c32.ckpt_id)]["tok_out"].max()] for a in ("sonnet55-medium", "opus55-medium")]
out += [pd.DataFrame(rows, columns=["arm", "n", "mean 64k-32k", "truncated rounds 32k", "truncated rounds 64k", "max out tokens 32k run", "max out tokens 64k run"]).round(3).to_markdown(index=False), "",
        f"All main-study runs: truncated rounds {int(full['n_budget_exhausted'].sum())} of {int(full['n_rounds'].sum())}; max output tokens in a single run: {int(full['tok_out'].max())} (cap 64000).", ""]
Path(ROOT / "reports/A3_BLIND_CAP.md").write_text("\n".join(out)); print("\n".join(out))
